public static long countByStep(int start, int end, int step) {
    if (step <= 0) return 0;
    long count = 0;
    if (start < end) {
        for (long current = start; current <= end; current += step) count++;
    } else if (start > end) {
        for (long current = start; current >= end; current -= step) count++;
    } else {
        count = 1;
    }
    return count;
}

