public static String multiplicationTable(int n) {
    if (n <= 0) return "";
    StringBuilder table = new StringBuilder();
    for (long i = 1; i <= n; i++) {
        for (long j = 1; j <= n; j++) {
            table.append(i).append(" x ").append(j).append(" = ").append(i * j);
            if (j < n) table.append(" | ");
        }
        if (i < n) table.append('\n');
    }
    return table.toString();
}

public static int countAlternatingParityRows(int[][] matrix) {
    if (matrix == null || matrix.length == 0) return 0;
    int count = 0;
    for (int[] row : matrix) {
        if (row == null || row.length == 0) continue;
        int i = 1;
        while (i < row.length) {
            if (row[i] % 2 == row[i - 1] % 2) break;
            i++;
        }
        if (i == row.length) count++;
    }
    return count;
}

