public static int gcdNonnegative(int first, int second) {
    if (first < 0 || second < 0) return -1;
    if (first == 0 && second == 0) return 0;
    int remainder;
    do {
        remainder = first % second;
        first = second;
        second = remainder;
    } while (second != 0);
    return first;
}

