        return 0;
    }

    if (number == 0) {
        return digit == 0 ? 1 : 0;
    }

    int count = 0;
    while (number != 0) {
        if (Math.abs(number % 10) == digit) {
            count++;
        }
        number /= 10;
    }
    return count;
}

