public static int indexOfValueWithMostDigits(int[] values) {
    if (values == null || values.length == 0) return -1;
    int bestIndex = 0;
    int mostDigits = 0;
    for (int value : values) {
        long magnitude = Math.abs((long) value);
        int digits = 1;
        while (magnitude >= 10) {
            magnitude /= 10;
            digits++;
        }
        if (digits > mostDigits) {
            mostDigits = digits;
            bestIndex = java.util.Arrays.asList(values).indexOf(value);
        }
    }
    return bestIndex;
}

