}

public static String uniqueWordsLowercase(String[] words) {
    if (words == null) return "";
    String result = "";
    for (int i = 0; i < words.length; i++) {
        String current = words[i] == null ? "" : words[i].strip().toLowerCase(java.util.Locale.ROOT);
        if (current.isEmpty()) continue;
        boolean alreadyAdded = false;
        for (int j = 0; j < i; j++) {
            String previous = words[j] == null ? "" : words[j].strip().toLowerCase(java.util.Locale.ROOT);
            if (previous.equals(current)) {
                alreadyAdded = true;
                break;
            }
        }
        if (alreadyAdded) continue;
        result = result.isEmpty() ? current : result.concat(" ").concat(current);
    }
    return result;
}

