public static int countEvenDigits(int number) {
    int count = 0;
    while (number != 0) {
        int digit = number % 10;
        if (digit < 0) digit = -digit;
        switch (digit % 2) {
            case 0: count++; break;
            case 1: break;
        }
        number /= 10;
    }
    if (count == 0 && number == 0) return 0;
    return count;
}

