public static int[] bubblePass(int[] values, int direction) {
    int[] result = values == null ? new int[0] : java.util.Arrays.copyOf(values, values.length);
    switch (direction) {
        case 1:
            for (int i = 0; i < result.length - 1; i++) {
                if (result[i] > result[i + 1]) { int temp = result[i]; result[i] = result[i + 1]; result[i + 1] = temp; }
            }
            break;
        case -1:
            for (int i = 0; i < result.length - 1; i++) {
                if (result[i] < result[i + 1]) { int temp = result[i]; result[i] = result[i + 1]; result[i + 1] = temp; }
            }
            break;
        default: break;
    }
    return result;
}

