public static int[] bubblePass(int[] values, int direction) {
    if (values == null) {
        return new int[0];
    }
    int[] result = values.clone();
    if (direction != 1 && direction != -1) {
        return result;
    }
    for (int i = 0; i < result.length - 1; i++) {
        if ((direction == 1 && result[i] > result[i + 1]) ||
            (direction == -1 && result[i] < result[i + 1])) {
            int temp = result[i];
            result[i] = result[i + 1];
            result[i + 1] = temp;
        }
    }
    return result;
}

