    if (flags == null || flags.length == 0) return -1;
    int low = 0;
    int high = flags.length;
    while (low < high) {
        int middle = low + (high - low) / 2;
        if (flags[middle]) high = middle;
        else low = middle + 1;
    }
    if (low == flags.length) return -1;
    return low;
}

